    width: 56,
    height: 56,
    borderRadius: 28,
    backgroundColor: theme.palette.primary,
    alignItems: 'center',
    justifyContent: 'center',
    elevation: 4,
    shadowColor: theme.palette.primary,
  },
  modalOverlay: {
    flex: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.7)',
    justifyContent: 'flex-end',
  },
  modalContent: {
    backgroundColor: theme.palette.card,
    borderTopLeftRadius: theme.borderRadius.lg,
    borderTopRightRadius: theme.borderRadius.lg,
    padding: theme.spacing.lg,
  },
  modalHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: theme.spacing.lg,
  },
  modalTitle: {
    fontSize: 20,
    fontWeight: '700',
    color: theme.palette.text.primary,
  },
  input: {
    backgroundColor: theme.palette.background,
    borderRadius: theme.borderRadius.md,
    padding: theme.spacing.md,
    fontSize: 16,
    color: theme.palette.text.primary,
    borderWidth: 1,
    borderColor: theme.palette.border,
    marginBottom: theme.spacing.md,
  },
  textArea: {
    height: 100,
    textAlignVertical: 'top',
  },
  submitButton: {
    backgroundColor: theme.palette.primary,
    borderRadius: theme.borderRadius.md,
    padding: theme.spacing.md,
    alignItems: 'center',
    marginTop: theme.spacing.sm,
  },
  submitButtonText: {
    fontSize: 16,
    fontWeight: '600',
    color: theme.palette.background,
  },
});

export const theme = {
  palette: {
    background: '#020617',
    card: '#0f172a',
    primary: '#22d3ee',
    accent: '#f472b6',
    border: '#1e293b',
    text: {
      primary: '#f8fafc',
      secondary: '#94a3b8',
    },
    success: '#4ade80',
    warning: '#fbbf24',
    error: '#f87171',
  },
  spacing: {
    xs: 4,
    sm: 8,
    md: 16,
    lg: 24,
    xl: 36,
  },
  borderRadius: {
    sm: 6,
    md: 10,
    lg: 18,
    pill: 999,
  },
} as const;

export type Theme = typeof theme;

// Android-only Expo config with build-profile variant support.
  // Variant is driven via eas.json -> build.<profile>.env.APP_VARIANT.
  const baseExpo = {
  icon: './assets/icon.png',
  platforms: ['android'],
  name: 'CRUD Template',
  slug: 'crud-template',
  version: '1.0.0',
  orientation: 'portrait',
  userInterfaceStyle: 'dark',
  newArchEnabled: true,
  splash: {
    image: './assets/splash.png',
    resizeMode: 'contain',
    backgroundColor: '#020617',
  },
  android: {
    package: 'com.yourcompany.crudtemplate',
    adaptiveIcon: {
      foregroundImage: './assets/adaptive-icon.png',
      backgroundColor: '#020617',
    },
  },
  extra: {
    eas: {
      projectId: '',
    },
  },
};

  const getVariant = () => {
    const v =
      process.env.APP_VARIANT ||
      process.env.BUILD_PROFILE ||
      process.env.EAS_BUILD_PROFILE ||
      "preview";
    return String(v).toLowerCase();
  };

  module.exports = ({ config }) => {
    const variant = getVariant();
    const isDev = variant === "development";

    return {
      expo: {
        ...baseExpo,
        // Keep anything Expo injects (rare in our case), but never allow iOS.
        ...(config?.expo || {}),
        platforms: ["android"],
        updates: {
          ...(baseExpo.updates || {}),
          ...((config?.expo || {}).updates || {}),
          enabled: !isDev,
        },
        extra: {
          ...(baseExpo.extra || {}),
          ...((config?.expo || {}).extra || {}),
          appVariant: variant,
        },
      },
    };
  };

import { registerRootComponent } from "expo";
import App from "./App";

registerRootComponent(App);

